def rle_encode(s):
    if not s:
        return ""
    out = []
    current, count = s[0], 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            out.append(str(count) + current)
            current, count = ch, 1
    out.append(str(count) + current)
    return "".join(out)


def rle_decode(s):
    out = []
    digits = ""
    for ch in s:
        if ch.isdigit():
            digits += ch
        else:
            out.append(ch * int(digits))
            digits = ""
    return "".join(out)

